/*
===============================================================================
DEFINICIÓN CANÓNICA VERSIONADA
Procedimiento: integracion_datos_analitica.usp_ejecutar_diario_claro

Origen:
- definición validada en producción el 18/09/2026;
- corrección CLARO EVOLUTION transitoria V2;
- conserva las guardas históricas existentes;
- no habilita el modo histórico de Gobierno para Administrativo.

No editar una migración histórica para desplegar este cambio. Esta definición
representa el estado canónico que debe quedar instalado.
===============================================================================
*/

CREATE OR ALTER PROCEDURE [integracion_datos_analitica].[usp_ejecutar_diario_claro]      @fecha_ejecucion DATE = NULL,      @codigo_unidad_negocio VARCHAR(20) = 'ADMINISTRATIVO',      @ejecutar_pasos_compartidos BIT = 1  AS  BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      DECLARE @today DATE =         CONVERT(DATE, SYSDATETIME());      DECLARE @expected_run_date DATE =         DATEADD(DAY, -1, @today);      /*        Fecha de inicio de la operación diaria observada.        Todo lo anterior pertenece al bootstrap histórico EVOL.        Esta protección evita que una ejecución manual del Job el        19/08 vuelva a etiquetar el snapshot mutable actual como 18/08.     */     DECLARE @first_operational_snapshot_date DATE = '2026-08-19';      SET @fecha_ejecucion =         ISNULL(@fecha_ejecucion, @expected_run_date);      /*        Protección importante:        este SP operacional NO sirve para backdate arbitrario.        Los huecos históricos se reparan con        usp_fill_claro_historical_snapshot_gaps.     */     IF @fecha_ejecucion <> @expected_run_date         THROW 53300,             '@fecha_ejecucion debe ser exactamente D-1. Para fechas anteriores use el gap fill histórico.',             1;      IF @fecha_ejecucion < @first_operational_snapshot_date         THROW 53312,             'La operación diaria observada inicia el 2026-08-19. Fechas anteriores deben permanecer como histórico EVOL.',             1;      SET @codigo_unidad_negocio =          UPPER(LTRIM(RTRIM(ISNULL(@codigo_unidad_negocio, ''))));        IF @codigo_unidad_negocio NOT IN ('ADMINISTRATIVO', 'GOBIERNO')          THROW 53313,              '@codigo_unidad_negocio debe ser ADMINISTRATIVO o GOBIERNO.',              1;        DECLARE @business_unit_name VARCHAR(150) =          CASE @codigo_unidad_negocio              WHEN 'ADMINISTRATIVO' THEN 'CLARO ADMINISTRATIVO'              WHEN 'GOBIERNO' THEN 'CLARO GOBIERNO'          END;        DECLARE @nombre_cliente_origen VARCHAR(150) =          CASE @codigo_unidad_negocio              WHEN 'ADMINISTRATIVO' THEN 'CLARO CORPORATIVO'              WHEN 'GOBIERNO' THEN 'CLARO GOBIERNO'          END;       DECLARE          @id_cliente_crm       INT          = 95,          @codigo_cliente         VARCHAR(50)  = 'CLARO',          @nombre_cliente         VARCHAR(150) = 'CLARO CORPORATIVO',          @target_source_code  VARCHAR(50)  = 'CLARO_BASE_GOALS',          @supervisor_source   VARCHAR(50)  = 'AVAL_COB_45';       DECLARE @anio_campana SMALLINT =         YEAR(@fecha_ejecucion);      DECLARE @mes_campana TINYINT =         MONTH(@fecha_ejecucion);      DECLARE @codigo_campana VARCHAR(7) =         CONCAT(             @anio_campana,             '-',             RIGHT(CONCAT('0', @mes_campana), 2)         );      DECLARE @campaign_start DATE =         DATEFROMPARTS(             @anio_campana,             @mes_campana,             1         );      DECLARE @historical_fill_to DATE =         DATEADD(DAY, -1, @fecha_ejecucion);      DECLARE @date_key INT =         CONVERT(             INT,             CONVERT(CHAR(8), @fecha_ejecucion, 112)         );      DECLARE @fecha_corte DATETIME2(3) =         DATEADD(             MILLISECOND,             -3,             DATEADD(                 DAY,                 1,                 CONVERT(DATETIME2(3), @fecha_ejecucion)             )         );       DECLARE         @stage NVARCHAR(200) = N'Inicio',          @client_key INT,         @campaign_key INT,          @snapshot_rows INT,         @assigned BIGINT,         @managed BIGINT,         @pending BIGINT,          @evolution_rows_run_date INT,         @evolution_portfolios_run_date INT,          @snapshot_without_evolution INT,         @evolution_without_snapshot INT,          @live_management DECIMAL(19,4),         @advisor_management DECIMAL(19,4),          @live_promises DECIMAL(19,4),         @advisor_promises DECIMAL(19,4),          @live_promises_amount DECIMAL(19,4),         @advisor_promises_amount DECIMAL(19,4),          @recovered DECIMAL(19,4),         @target DECIMAL(19,4);       BEGIN TRY          BEGIN TRANSACTION;           /* ========================================================            1. SCOPE            ======================================================== */          SET @stage = CONCAT(N'1. Scope [', @codigo_unidad_negocio, N']');         PRINT @stage;          EXEC integracion_datos_analitica.usp_asegurar_alcance_campana_claro             @id_cliente_crm = @id_cliente_crm,             @codigo_cliente = @codigo_cliente,             @nombre_cliente = @nombre_cliente,             @anio_campana = @anio_campana,             @mes_campana = @mes_campana,              @codigo_unidad_negocio = @codigo_unidad_negocio;            SELECT             @client_key = c.clave_cliente         FROM analitica.dim_cliente AS c         WHERE c.id_cliente_crm = @id_cliente_crm;           SELECT             @campaign_key = c.clave_campana         FROM analitica.dim_campana AS c         WHERE c.clave_cliente = @client_key           AND c.codigo_campana = @codigo_campana;           IF @client_key IS NULL OR @campaign_key IS NULL             THROW 53301,                 'No se pudo resolver clave_cliente/clave_campana.',                 1;           /* ========================================================            2. EVOLUTION            Reproceso idempotente del mes correspondiente a D-1.            ======================================================== */          SET @stage = CONCAT(N'2. Evolution [', @codigo_unidad_negocio, N']');         PRINT @stage;          EXEC integracion_datos_analitica.usp_cargar_evolucion_cartera_claro
             @id_cliente_crm = @id_cliente_crm,
             @anio_campana = @anio_campana,
             @mes_campana = @mes_campana,
             @codigo_unidad_negocio = @codigo_unidad_negocio,
             @normalizar_desfase_transitorio = 1;           /* ========================================================            3. READINESS DE FUENTE             No se captura el snapshot mutable si EVOL todavía no            contiene el día que se pretende cerrar.            ======================================================== */          SET @stage = CONCAT(N'3. Validación cierre EVOL D-1 [', @codigo_unidad_negocio, N']');         PRINT @stage;          SELECT             @evolution_rows_run_date = COUNT(*),             @evolution_portfolios_run_date =                 COUNT(DISTINCT e.clave_cartera)         FROM analitica.hecho_evolucion_cartera_diario AS e          INNER JOIN analitica.dim_cartera AS bp              ON bp.clave_cartera = e.clave_cartera             AND bp.clave_cliente = @client_key             AND bp.unidad_negocio_origen = @business_unit_name          WHERE e.clave_cliente = @client_key            AND e.clave_campana = @campaign_key            AND e.clave_fecha = @date_key;           IF ISNULL(@evolution_rows_run_date, 0) = 0         BEGIN             DECLARE @readiness_message NVARCHAR(2048) =                 CONCAT(                     'EVOL aún no contiene el cierre ',                     CONVERT(VARCHAR(10), @fecha_ejecucion, 120),                     '. SQL Agent debe reintentar más tarde.'                 );              THROW 53302, @readiness_message, 1;         END;           /* ========================================================            4. TARGET STAGED AUTOMÁTICO             En un mes nuevo crea la fila staged reutilizando la            última meta canonical vigente.            ======================================================== */          SET @stage = CONCAT(N'4. Ensure Target Stage [', @codigo_unidad_negocio, N']');          PRINT @stage;            IF @ejecutar_pasos_compartidos = 1          BEGIN              EXEC integracion_datos_analitica.usp_asegurar_meta_claro_preparada                  @anio_campana = @anio_campana,                  @mes_campana = @mes_campana,                  @codigo_origen = @target_source_code;          END;           /* ========================================================            5. HISTORICAL GAP FILL             Solo días ANTERIORES a @fecha_ejecucion.            Nunca sobreescribe snapshots canonical existentes.            ======================================================== */          SET @stage = CONCAT(N'5. Historical Gap Fill [', @codigo_unidad_negocio, N']');         PRINT @stage;          IF @historical_fill_to >= @campaign_start         BEGIN              EXEC integracion_datos_analitica.usp_completar_vacios_cortes_historicos_claro                  @id_cliente_crm = @id_cliente_crm,                  @anio_campana = @anio_campana,                  @mes_campana = @mes_campana,                  @fecha_desde = @campaign_start,                  @fecha_hasta = @historical_fill_to,                  @solo_faltantes = 1,                  @codigo_unidad_negocio = @codigo_unidad_negocio;          END;           /* ========================================================            6. LIVE            ======================================================== */          SET @stage = CONCAT(N'6. Live Operations [', @codigo_unidad_negocio, N']');         PRINT @stage;          EXEC integracion_datos_analitica.usp_cargar_operaciones_actuales_claro              @id_cliente_crm = @id_cliente_crm,              @fecha_corte = @fecha_corte,              @anio_campana = @anio_campana,              @mes_campana = @mes_campana,              @nombre_cliente_origen = @nombre_cliente_origen,              @codigo_unidad_negocio = @codigo_unidad_negocio;           /* ========================================================            7. ADVISOR            ======================================================== */          SET @stage = CONCAT(N'7. Advisor [', @codigo_unidad_negocio, N']');         PRINT @stage;          EXEC integracion_datos_analitica.usp_cargar_asesor_diario_claro              @id_cliente_crm = @id_cliente_crm,              @fecha_corte = @fecha_corte,              @anio_campana = @anio_campana,              @mes_campana = @mes_campana,              @nombre_cliente_origen = @nombre_cliente_origen,              @codigo_unidad_negocio = @codigo_unidad_negocio;           /* ========================================================            8. SNAPSHOT OBSERVADO D-1             Solo se llega aquí si EVOL confirmó el día.            ======================================================== */          SET @stage = CONCAT(N'8. Daily Snapshot [', @codigo_unidad_negocio, N']');         PRINT @stage;          EXEC integracion_datos_analitica.usp_cargar_corte_diario_cartera_claro              @id_cliente_crm = @id_cliente_crm,              @fecha_corte = @fecha_ejecucion,              @anio_campana = @anio_campana,              @mes_campana = @mes_campana,              @codigo_unidad_negocio = @codigo_unidad_negocio;           /* ========================================================            9. TARGET            ======================================================== */          SET @stage = CONCAT(N'9. Target [', @codigo_unidad_negocio, N']');          PRINT @stage;            IF @ejecutar_pasos_compartidos = 1          BEGIN              EXEC integracion_datos_analitica.usp_cargar_meta_mensual_claro                  @id_cliente_crm = @id_cliente_crm,                  @codigo_campana = @codigo_campana,                  @codigo_origen = @target_source_code;          END;           /* ========================================================            10. SUPERVISOR            ======================================================== */          SET @stage = CONCAT(N'10. Supervisor [', @codigo_unidad_negocio, N']');          PRINT @stage;            IF @ejecutar_pasos_compartidos = 1          BEGIN              EXEC integracion_datos_analitica.usp_cargar_historial_jerarquia_supervisor_claro                  @id_cliente_crm = @id_cliente_crm,                  @anio_campana = @anio_campana,                  @mes_campana = @mes_campana,                  @codigo_origen = @supervisor_source;          END;           /* ========================================================            11. VALIDACIÓN SNAPSHOT D-1            ======================================================== */          SET @stage = CONCAT(N'11. Validación Snapshot [', @codigo_unidad_negocio, N']');         PRINT @stage;          SELECT             @snapshot_rows =                 SUM(                     CASE                         WHEN f.tiene_corte_origen = 1                             THEN 1                         ELSE 0                     END                 ),              @assigned =                 SUM(                     CASE                         WHEN f.tiene_corte_origen = 1                             THEN f.clientes_asignados_corte                         ELSE 0                     END                 ),              @managed =                 SUM(                     CASE                         WHEN f.tiene_corte_origen = 1                             THEN f.clientes_gestionados_corte                         ELSE 0                     END                 ),              @pending =                 SUM(                     CASE                         WHEN f.tiene_corte_origen = 1                             THEN f.clientes_pendientes_corte                         ELSE 0                     END                 )          FROM analitica.hecho_cartera_diario AS f          INNER JOIN analitica.dim_cartera AS bp              ON bp.clave_cartera = f.clave_cartera             AND bp.clave_cliente = @client_key             AND bp.unidad_negocio_origen = @business_unit_name          WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key            AND f.clave_fecha = @date_key;           IF ISNULL(@snapshot_rows, 0) = 0             THROW 53303,                 'No existe snapshot canonical para D-1.',                 1;           IF ISNULL(@assigned, 0)            <> ISNULL(@managed, 0)               + ISNULL(@pending, 0)              THROW 53304,                 'Snapshot diario: assigned <> managed + pending.',                 1;           /* ========================================================            12. RECONCILIACIÓN SNAPSHOT D-1 vs EVOLUTION D-1             Deben ser exactamente las mismas combinaciones            cartera-fecha canonical.            ======================================================== */          SET @stage = CONCAT(N'12. Validación Snapshot vs Evolution [', @codigo_unidad_negocio, N']');         PRINT @stage;           SELECT             @snapshot_without_evolution = COUNT(*)          FROM analitica.hecho_cartera_diario AS f          INNER JOIN analitica.dim_cartera AS bp              ON bp.clave_cartera = f.clave_cartera             AND bp.clave_cliente = @client_key             AND bp.unidad_negocio_origen = @business_unit_name          WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key            AND f.clave_fecha = @date_key            AND f.tiene_corte_origen = 1            AND NOT EXISTS           (               SELECT 1               FROM analitica.hecho_evolucion_cartera_diario AS e               WHERE e.clave_cliente = f.clave_cliente                 AND e.clave_campana = f.clave_campana                 AND e.clave_fecha = f.clave_fecha                 AND e.clave_cartera = f.clave_cartera           );           SELECT             @evolution_without_snapshot = COUNT(*)          FROM analitica.hecho_evolucion_cartera_diario AS e          INNER JOIN analitica.dim_cartera AS bp              ON bp.clave_cartera = e.clave_cartera             AND bp.clave_cliente = @client_key             AND bp.unidad_negocio_origen = @business_unit_name          WHERE e.clave_cliente = @client_key            AND e.clave_campana = @campaign_key            AND e.clave_fecha = @date_key            AND NOT EXISTS           (               SELECT 1               FROM analitica.hecho_cartera_diario AS f               WHERE f.clave_cliente = e.clave_cliente                 AND f.clave_campana = e.clave_campana                 AND f.clave_fecha = e.clave_fecha                 AND f.clave_cartera = e.clave_cartera                 AND f.tiene_corte_origen = 1           );           IF ISNULL(@snapshot_without_evolution, 0) <> 0             THROW 53305,                 'Existen snapshots D-1 sin cartera correspondiente en Evolution.',                 1;           IF ISNULL(@evolution_without_snapshot, 0) <> 0             THROW 53306,                 'Existen carteras Evolution D-1 sin snapshot canonical.',                 1;           IF ISNULL(@snapshot_rows, 0)            <> ISNULL(@evolution_portfolios_run_date, 0)              THROW 53307,                 'Cantidad de carteras Snapshot D-1 <> Evolution D-1.',                 1;           /* ========================================================            13. RECONCILIACIÓN LIVE vs ADVISOR MTD            ======================================================== */          SET @stage = CONCAT(N'13. Validación Live vs Advisor [', @codigo_unidad_negocio, N']');         PRINT @stage;           SELECT             @live_management =                 SUM(f.eventos_gestion_dia),              @live_promises =                 SUM(f.cantidad_promesas_dia),              @live_promises_amount =                 SUM(f.monto_promesas_dia),              @recovered =                 SUM(f.monto_recuperado_dia)          FROM analitica.hecho_cartera_diario AS f          INNER JOIN analitica.dim_fecha AS d              ON d.clave_fecha = f.clave_fecha          INNER JOIN analitica.dim_cartera AS bp              ON bp.clave_cartera = f.clave_cartera             AND bp.clave_cliente = @client_key             AND bp.unidad_negocio_origen = @business_unit_name          WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key            AND d.fecha_calendario >= @campaign_start            AND d.fecha_calendario <= @fecha_ejecucion;           SELECT             @advisor_management =                 SUM(f.eventos_gestion),              @advisor_promises =                 SUM(f.cantidad_promesas),              @advisor_promises_amount =                 SUM(f.monto_promesas)          FROM analitica.hecho_asesor_diario AS f          INNER JOIN analitica.dim_fecha AS d              ON d.clave_fecha = f.clave_fecha          INNER JOIN analitica.dim_cartera AS bp              ON bp.clave_cartera = f.clave_cartera             AND bp.clave_cliente = @client_key             AND bp.unidad_negocio_origen = @business_unit_name          WHERE f.clave_cliente = @client_key            AND f.clave_campana = @campaign_key            AND d.fecha_calendario >= @campaign_start            AND d.fecha_calendario <= @fecha_ejecucion;           IF ISNULL(@live_management, 0)            <> ISNULL(@advisor_management, 0)              THROW 53308,                 'Live eventos_gestion <> Advisor.',                 1;           IF ISNULL(@live_promises, 0)            <> ISNULL(@advisor_promises, 0)              THROW 53309,                 'Live cantidad_promesas <> Advisor.',                 1;           IF ISNULL(@live_promises_amount, 0)            <> ISNULL(@advisor_promises_amount, 0)              THROW 53310,                 'Live monto_promesas <> Advisor.',                 1;           /* ========================================================            14. TARGET            ======================================================== */          SET @stage = CONCAT(N'14. Validación Target [', @codigo_unidad_negocio, N']');         PRINT @stage;           IF @ejecutar_pasos_compartidos = 1          BEGIN              SELECT                  @target = t.meta_monto_recuperado              FROM analitica.hecho_meta_mensual AS t              WHERE t.clave_cliente = @client_key                AND t.clave_campana = @campaign_key                AND t.clave_cartera IS NULL;                IF @target IS NULL                  THROW 53311,                      'No existe Target mensual.',                      1;          END          ELSE          BEGIN              SET @target = NULL;          END;           /* ========================================================            COMMIT            ======================================================== */          COMMIT TRANSACTION;           SELECT              @fecha_ejecucion AS run_date,              @codigo_campana AS codigo_campana,              @codigo_unidad_negocio AS codigo_unidad_negocio,              @business_unit_name AS unidad_negocio_origen,              @client_key AS clave_cliente,              @campaign_key AS clave_campana,              @snapshot_rows AS snapshot_portfolios,              @assigned AS clientes_asignados,              @managed AS clientes_gestionados,              @pending AS clientes_pendientes,              @live_management AS eventos_gestion,              @live_promises AS cantidad_promesas,              @live_promises_amount AS monto_promesas,              @recovered AS monto_recuperado,              CASE                  WHEN @codigo_unidad_negocio = 'ADMINISTRATIVO'                   AND @ejecutar_pasos_compartidos = 1                      THEN @target                  ELSE NULL              END AS meta_monto_recuperado,              CASE                  WHEN @codigo_unidad_negocio = 'ADMINISTRATIVO'                   AND @ejecutar_pasos_compartidos = 1                      THEN CAST(                          @recovered / NULLIF(@target, 0)                          AS DECIMAL(18,6)                      )                  ELSE NULL              END AS tasa_cumplimiento_meta,              CASE                  WHEN @ejecutar_pasos_compartidos = 0                      THEN 'DEFERRED_SHARED_STEP'                  WHEN @codigo_unidad_negocio = 'ADMINISTRATIVO'                      THEN 'CLIENT_CAMPAIGN_GLOBAL'                  ELSE 'CLIENT_GLOBAL_NOT_UNIT_SPECIFIC'              END AS target_scope,              @ejecutar_pasos_compartidos AS shared_steps_executed,              CASE                  WHEN @codigo_unidad_negocio = 'ADMINISTRATIVO'                   AND @ejecutar_pasos_compartidos = 1                      THEN 'CLARO_DAILY_LOAD_OK'                  ELSE 'CLARO_DAILY_BUSINESS_UNIT_LOAD_OK'              END AS assessment;       END TRY     BEGIN CATCH          IF XACT_STATE() <> 0             ROLLBACK TRANSACTION;           SELECT              @codigo_unidad_negocio AS codigo_unidad_negocio,              @business_unit_name AS unidad_negocio_origen,              @stage AS failed_stage,              ERROR_NUMBER() AS error_number,             ERROR_PROCEDURE() AS error_procedure,             ERROR_LINE() AS error_line,             ERROR_MESSAGE() AS error_message,              @@TRANCOUNT AS open_transactions,             XACT_STATE() AS xact_state,              'ROLLBACK_COMPLETO_DAILY'                 AS assessment;          THROW;      END CATCH;  END;
GO
